R,C=len(a),len(a[0]); ext=set(); q=deque()
for i in range(R):
 for j in (0,C-1):
  if a[i][j]==1 and (i,j) not in ext: ext.add((i,j)); q.append((i,j))
for j in range(C):
 for i in (0,R-1):
  if a[i][j]==1 and (i,j) not in ext: ext.add((i,j)); q.append((i,j))
while q:
 i,j=q.popleft()
 for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
  ni,nj=i+di,j+dj
  if 0<=ni<R and 0<=nj<C and a[ni][nj]==1 and (ni,nj) not in ext:
   ext.add((ni,nj));q.append((ni,nj))
interior=[(i,j) for i in range(R) for j in range(C) if a[i][j]==1 and (i,j) not in ext]
